func (w *reviewBoundedCapture) Write(p []byte) (int, error) {
	w.mu.Lock()
	defer w.mu.Unlock()
	n := len(p)
	remaining := w.limit - int64(w.buf.Len())
	if int64(n) > remaining {
		w.buf.Write(p[:int(remaining)])
		w.overflow = true
		if w.cancel != nil {
			w.cancel()
		}
	} else {
